function subsets(items) {
  const result = []
  const current = []
  function explore(i) {
    if (i === items.length) {
      result.push([...current])
      return
    }
    explore(i + 1)
    current.push(items[i])
    explore(i + 1)
    current.pop()
  }
  explore(0)
  return result
}
